import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import process from 'node:process';

const SOURCE_PATH = 'docs/data/scientific-session-catalog.json';
const OUTPUT_PATH = 'docs/data/scientific-observation-index.json';
const ALGORITHM_VERSION = '1.1.0';

const stableJson = (value) => `${JSON.stringify(value, null, 2)}\n`;
const digest = (value) => `sha256:${createHash('sha256').update(value).digest('hex')}`;
const slug = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'UNKNOWN';
const assert = (condition, message) => { if (!condition) throw new Error(message); };
const isKnown = (value) => { const normalized = String(value ?? '').trim().toUpperCase(); return Boolean(normalized) && normalized !== 'UNKNOWN' && normalized !== 'N/A'; };
const normalizeQuality = (value) => { const normalized = String(value || 'UNKNOWN').toUpperCase(); if (normalized === 'VALIDATED_ANALYTICS') return 'ACCEPTED'; if (normalized === 'ATTENTION_REQUIRED') return 'DEGRADED'; if (normalized === 'METADATA_INCOMPLETE') return 'INCOMPLETE'; return normalized; };
const qualityWeight = (value) => { const normalized = normalizeQuality(value); if (normalized === 'ACCEPTED') return 1; if (normalized === 'DEGRADED') return 0.6; if (normalized === 'INCOMPLETE') return 0.4; return 0.2; };
const buildCatalogItem = (session, sourceDigest, sourceVersion) => ({schemaVersion:'1.1',catalogItemId:`CAT-SESSION-${slug(session.sessionId)}`,entityType:'OBSERVATION_SESSION',entityId:session.sessionId,sourceSystem:'scientific-session-catalog.json',sourceVersion,sourceDigest,catalogState:'INDEXABLE',qualityState:normalizeQuality(session.qualityState),analyticsState:session.analyticsState||null,metadataState:session.metadataState||null,recordVersion:1,indexedAtUtc:null,lastReconciledAtUtc:null,reconciliationState:'MATCHED',supersedesCatalogItemId:null});
const buildSearchDocument = (session,catalogItemId,indexBuildId,sourceDigest)=>({schemaVersion:'1.1',searchDocumentId:`SRCH-${catalogItemId}-V1`,catalogItemId,indexBuildId,documentType:'SCIENTIFIC_SESSION',title:`${session.target} · ${session.observationDate}`,summary:[`Sessione ${session.sessionId}`,isKnown(session.filter)?`filtro ${session.filter}`:null,isKnown(session.telescope)?`telescopio ${session.telescope}`:null,isKnown(session.camera)?`camera ${session.camera}`:null,Number.isFinite(session.integrationHours)?`${session.integrationHours} h di integrazione`:null,normalizeQuality(session.qualityState)==='INCOMPLETE'?'metadata scientifici incompleti':null].filter(Boolean).join(' · '),normalizedText:[session.target,session.sessionId,session.observationDate,session.configurationId,session.telescope,session.camera,session.filter,session.binning,session.qualityState,session.analyticsState,session.metadataState,session.transferState,session.manifestState,session.evidenceState,session.weather?.detail?.dominantCloudCondition,session.weather?.detail?.dominantWindCondition].filter(isKnown).join(' ').toLowerCase(),keywords:[...new Set([isKnown(session.target)?slug(session.target).toLowerCase():null,isKnown(session.telescope)?slug(session.telescope).toLowerCase():null,isKnown(session.camera)?slug(session.camera).toLowerCase():null,isKnown(session.filter)?slug(session.filter).toLowerCase():null,String(session.observationDate||'').slice(0,4),normalizeQuality(session.qualityState).toLowerCase()].filter(Boolean))],facetValues:{target:[session.target].filter(isKnown),year:[String(session.observationDate||'').slice(0,4)].filter(Boolean),telescope:[session.telescope].filter(isKnown),camera:[session.camera].filter(isKnown),filter:[session.filter].filter(isKnown),quality:[normalizeQuality(session.qualityState)]},sourceUrl:`scientific-session-detail/?sessionId=${encodeURIComponent(session.sessionId)}`,rankingSignals:{qualityWeight:qualityWeight(session.qualityState),metadataCompleteness:[session.target,session.observationDate,session.configurationId,session.telescope,session.camera,session.filter,session.qualityState].filter(isKnown).length/7,integrationHours:Number(session.integrationHours||0)},sourceDigest});
const buildOutput=(sourceText,source)=>{assert(['1.0','1.1','1.2','1.3','1.4','1.5'].includes(source?.schemaVersion),'Unsupported scientific session catalog schema');assert(Array.isArray(source.sessions),'sessions must be an array');const sourceDigest=digest(sourceText);const buildKey=sourceDigest.split(':')[1].slice(0,14).toUpperCase();const indexBuildId=`IDX-${buildKey}`;const catalogItems=[];const searchDocuments=[];const reconciliationRecords=[];for(const session of [...source.sessions].sort((a,b)=>String(a.sessionId).localeCompare(String(b.sessionId)))){assert(session.sessionId,'Every session requires sessionId');assert(session.observationDate,`Session ${session.sessionId} requires observationDate`);const sessionDigest=digest(stableJson(session));const item=buildCatalogItem(session,sessionDigest,source.schemaVersion);const document=buildSearchDocument(session,item.catalogItemId,indexBuildId,sessionDigest);catalogItems.push(item);searchDocuments.push(document);reconciliationRecords.push({reconciliationRecordId:`REC-${indexBuildId}-${String(reconciliationRecords.length+1).padStart(3,'0')}`,indexBuildId,catalogItemId:item.catalogItemId,sourceDigestExpected:sessionDigest,sourceDigestObserved:sessionDigest,reconciliationState:'MATCHED',differenceType:null,detectedAtUtc:null,resolvedAtUtc:null,resolutionReference:null});}const projection={schemaVersion:'1.1',algorithmVersion:ALGORITHM_VERSION,generatedFrom:SOURCE_PATH,sourceSnapshotDigest:sourceDigest,indexBuild:{indexBuildId,algorithmVersion:ALGORITHM_VERSION,sourceSnapshotDigest:sourceDigest,documentCount:searchDocuments.length,failureCount:0,buildStatus:'COMPLETED'},summary:{sessionCount:source.sessions.length,catalogItemCount:catalogItems.length,searchDocumentCount:searchDocuments.length,reconciliationMatched:reconciliationRecords.filter(record=>record.reconciliationState==='MATCHED').length},catalogItems,searchDocuments,reconciliationRecords};projection.indexBuild.outputDigest=digest(stableJson({catalogItems,searchDocuments,reconciliationRecords}));return projection;};
const main=async()=>{const mode=process.argv[2]||'--check';assert(['--check','--write','--print'].includes(mode),`Unsupported mode: ${mode}`);const sourceText=await readFile(SOURCE_PATH,'utf8');const source=JSON.parse(sourceText);const generated=stableJson(buildOutput(sourceText,source));if(mode==='--print'){process.stdout.write(generated);return;}if(mode==='--write'){await writeFile(OUTPUT_PATH,generated,'utf8');process.stdout.write(`Generated ${OUTPUT_PATH} from ${SOURCE_PATH}.\n`);return;}const current=await readFile(OUTPUT_PATH,'utf8').catch(()=>'');if(current!==generated){process.stderr.write('Scientific catalog drift detected. Run: node .github/scripts/generate-scientific-catalog.mjs --write\n');process.exitCode=1;return;}process.stdout.write('Scientific observation index is aligned with its governed source.\n');};
main().catch(error=>{console.error(error.message);process.exitCode=1;});
